import tarfile,io,lzma
names=sorted(q.name for q in out.iterdir());assert len(names)==13
originals={};total=0
for name in names:
 q=out/name;fd=os.open(q,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
 with os.fdopen(fd,'rb') as stream:
  a=os.fstat(stream.fileno());assert stat.S_ISREG(a.st_mode) and a.st_nlink==1 and a.st_size<=8*1024*1024
  assert total+a.st_size<=16*1024*1024
  content=stream.read(a.st_size+1);b=os.fstat(stream.fileno());c=q.lstat()
 assert len(content)==a.st_size and tuple(getattr(a,k) for k in keys)==tuple(getattr(b,k) for k in keys)==tuple(getattr(c,k) for k in keys)
 originals[name]=content;total+=len(content)
assert sorted(q.name for q in out.iterdir())==names
buf=io.BytesIO()
with tarfile.open(fileobj=buf,mode='w',format=tarfile.USTAR_FORMAT) as archive:
 for name,content in sorted(originals.items()):
  info=tarfile.TarInfo(name);info.size=len(content);info.mode=0o600;info.mtime=0;archive.addfile(info,io.BytesIO(content))
plain=buf.getvalue();compressed=lzma.compress(plain,preset=6)
assert lzma.decompress(compressed)==plain
put(out/'FULL-ORIGINALS.tar.xz',compressed)
